UPDATE drink_details dd
SET deleted_at = NOW() AT TIME ZONE 'Asia/Ho_Chi_Minh',
deleted_by = #{deletedBy}
FROM drinks d
WHERE dd.drink_detail_id = #{drinkDetailId}
AND d.drink_id = dd.drink_id
AND dd.deleted_at IS NULL
AND d.deleted_at IS NULL
AND d.is_deleted = FALSE

  AND d.shop_id = #{currentUserShopId}
